// One REST operation, generated by the api-catalog plugin: what it is, what it takes and
// returns, and how to call it.

import Link from '@docusaurus/Link';
import Translate, {translate} from '@docusaurus/Translate';
import Heading from '@theme/Heading';
import Layout from '@theme/Layout';
import {CopyButton, ExternalMark, Pill} from '@site/src/components/ui';
import {
  ApiShell,
  ErrorTable,
  GuideMarkdown,
  MethodBadge,
  ParameterTable,
  PathText,
  ResponsePanel,
  SamplesPanel,
  SchemaTable,
  useApiCatalog,
} from './parts';
import styles from './api.module.css';

function roleLabel(role) {
  return {
    public: translate({id: 'api.role.public', message: 'Public'}),
    member: translate({id: 'api.role.member', message: 'Signed-in member'}),
    admin: translate({id: 'api.role.admin', message: 'Administrator'}),
  }[role];
}

function Section({id, title, children}) {
  return (
    <section className={styles.section} aria-labelledby={id}>
      <Heading as="h2" id={id} className={styles.sectionTitle}>
        {title}
      </Heading>
      {children}
    </section>
  );
}

export default function OperationPage({operation}) {
  const {groups, operations} = useApiCatalog();
  const group = groups.find((candidate) => candidate.id === operation.group);
  const index = operations.findIndex((candidate) => candidate.id === operation.id);
  const previous = operations[index - 1];
  const next = operations[index + 1];
  const byPlace = (place) => operation.parameters.filter((parameter) => parameter.in === place);
  const guideDoc = operation.guide?.doc ?? group?.guide;
  const guideHref = operation.guide ? `/docs/${operation.guide.doc}${operation.guide.anchor ? `#${operation.guide.anchor}` : ''}` : null;

  return (
    <Layout title={`${operation.name} · REST API`} description={`${operation.method} ${operation.path}`}>
      <ApiShell current={operation.id}>
        <main className={styles.main}>
          <div className={styles.columns}>
            <div className={styles.details}>
              <nav className={styles.breadcrumbs} aria-label={translate({id: 'theme.docs.breadcrumbs.navAriaLabel', message: 'Breadcrumbs'})}>
                <ol>
                  <li>
                    <Link to="/docs">
                      <Translate id="docs.breadcrumbs.docs">Docs</Translate>
                    </Link>
                  </li>
                  <li>
                    <Link to="/docs/api">REST API</Link>
                  </li>
                  {group && <li>{group.title}</li>}
                  <li>
                    <span aria-current="page">{operation.name}</span>
                  </li>
                </ol>
              </nav>
              <Heading as="h1" className={styles.title}>
                {operation.name}
              </Heading>
              <div className={styles.pathBar}>
                <MethodBadge method={operation.method} />
                <code className={styles.path}>
                  <PathText path={operation.path} />
                </code>
                <CopyButton text={operation.path} label={translate({id: 'api.copyPath', message: 'Copy the path'})} />
              </div>
              <div className={styles.pills}>
                {operation.role ? (
                  <Pill>{roleLabel(operation.role)}</Pill>
                ) : (
                  <Pill tone="security">
                    <Translate id="api.signed">Signed request</Translate>
                  </Pill>
                )}
                {operation.method === 'GET' && (
                  <Pill tone="improved">
                    <Translate id="api.readOnly">Read-only</Translate>
                  </Pill>
                )}
              </div>
              {operation.proof && (
                <p className={styles.description}>
                  <Translate id="api.proof" values={{proof: <GuideMarkdown text={operation.proof} guideDoc={guideDoc} />}}>
                    {'Proven by {proof}, not by a session.'}
                  </Translate>
                </p>
              )}
              {operation.guide?.text && (
                <p className={styles.description}>
                  <GuideMarkdown text={operation.guide.text} guideDoc={guideDoc} />
                </p>
              )}
              <p className={styles.meta}>
                {guideHref && (
                  <Link to={guideHref}>
                    {operation.guide.heading ? (
                      <Translate id="api.readMore" values={{section: operation.guide.heading}}>
                        {'Read more: {section}'}
                      </Translate>
                    ) : (
                      <Translate id="api.readGuide">Read the guide</Translate>
                    )}
                  </Link>
                )}
                <Link to={operation.source}>
                  <Translate id="api.source" values={{handler: <code>{operation.javaMethod}</code>}}>
                    {'Source: {handler}'}
                  </Translate>
                  <ExternalMark size={11} />
                </Link>
              </p>

              {byPlace('path').length > 0 && (
                <Section id="path-parameters" title={translate({id: 'api.section.path', message: 'Path parameters'})}>
                  <ParameterTable caption={translate({id: 'api.section.path', message: 'Path parameters'})} parameters={byPlace('path')} />
                </Section>
              )}
              {byPlace('query').length > 0 && (
                <Section id="query-parameters" title={translate({id: 'api.section.query', message: 'Query parameters'})}>
                  <ParameterTable caption={translate({id: 'api.section.query', message: 'Query parameters'})} parameters={byPlace('query')} />
                </Section>
              )}
              {byPlace('header').length > 0 && (
                <Section id="headers" title={translate({id: 'api.section.headers', message: 'Headers'})}>
                  <ParameterTable caption={translate({id: 'api.section.headers', message: 'Headers'})} parameters={byPlace('header')} />
                </Section>
              )}
              {operation.body && (
                <Section id="request-body" title={translate({id: 'api.section.body', message: 'Request body'})}>
                  <p className={styles.note}>
                    <code>{operation.body.contentType}</code>
                    {!operation.body.required && (
                      <>
                        {' · '}
                        <Translate id="api.body.optional">The body is optional.</Translate>
                      </>
                    )}
                  </p>
                  {operation.body.schema.kind === 'binary' ? (
                    <p className={styles.note}>
                      <Translate id="api.body.raw">The provider’s JSON payload, exactly as it was signed.</Translate>
                    </p>
                  ) : (
                    <SchemaTable caption={translate({id: 'api.section.body', message: 'Request body'})} schema={operation.body.schema} />
                  )}
                </Section>
              )}
              <Section id="response" title={translate({id: 'api.section.response', message: 'Response'})}>
                <p className={styles.note}>
                  <Translate id="api.response.statuses" values={{statuses: <code>{operation.statuses.join(', ')}</code>}}>
                    {'Success: {statuses}'}
                  </Translate>
                </p>
                {operation.response ? (
                  <SchemaTable caption={translate({id: 'api.section.response', message: 'Response'})} schema={operation.response.schema} />
                ) : (
                  <p className={styles.note}>
                    <Translate id="api.response.none">No response body.</Translate>
                  </p>
                )}
              </Section>
              <Section id="errors" title={translate({id: 'api.section.errors', message: 'Errors'})}>
                <ErrorTable errors={operation.errors} guideDoc={guideDoc} />
              </Section>

              <nav className={styles.pager} aria-label={translate({id: 'api.pager.label', message: 'Previous and next operation'})}>
                {previous && (
                  <Link to={`/docs/api/${previous.id}`} className={styles.pagerLink}>
                    <span className={styles.pagerLabel}>{translate({id: 'theme.docs.paginator.previous', message: 'Previous'})}</span>
                    <span className={styles.pagerTitle}>← {previous.name}</span>
                  </Link>
                )}
                {next && (
                  <Link to={`/docs/api/${next.id}`} className={`${styles.pagerLink} ${styles.pagerNext}`}>
                    <span className={styles.pagerLabel}>{translate({id: 'theme.docs.paginator.next', message: 'Next'})}</span>
                    <span className={styles.pagerTitle}>{next.name} →</span>
                  </Link>
                )}
              </nav>
            </div>
            <div className={styles.samples}>
              <SamplesPanel operation={operation} />
              {operation.body && operation.body.schema.kind !== 'binary' && (
                <p className={styles.exampleNote}>
                  <Translate id="api.samples.exampleNote">The request body is an example built from the schema; replace every placeholder.</Translate>
                </p>
              )}
              <ResponsePanel operation={operation} />
            </div>
          </div>
        </main>
      </ApiShell>
    </Layout>
  );
}
